-- Executable proposed schema. Evolution requires a migration and round-trip tests.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE projects(project_id TEXT PRIMARY KEY, repo_path TEXT NOT NULL UNIQUE, host_epoch INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE specs(spec_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(project_id), sha256 TEXT NOT NULL CHECK(length(sha256)=64), revision INTEGER NOT NULL CHECK(revision>0), UNIQUE(project_id,revision));
CREATE TABLE runs(run_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(project_id), spec_id TEXT NOT NULL REFERENCES specs(spec_id), state TEXT NOT NULL CHECK(state IN ('CREATED','DISCOVERING','SPECIFYING','READY','RUNNING','VERIFYING','PAUSE_REQUESTED','PAUSED','WAITING_EXTERNAL','BLOCKED','CANCEL_REQUESTED','CANCELLED','INCOMPLETE','FAILED','COMPLETED')), mode TEXT NOT NULL CHECK(mode IN ('PLAN','BUILD','AUTO')), revision INTEGER NOT NULL DEFAULT 0, role_epoch INTEGER NOT NULL DEFAULT 1, resume_state TEXT, deadline_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE requirements(requirement_id TEXT NOT NULL, spec_id TEXT NOT NULL REFERENCES specs(spec_id), title TEXT NOT NULL, required_release INTEGER NOT NULL CHECK(required_release IN (0,1)), PRIMARY KEY(requirement_id,spec_id));
CREATE TABLE acceptance_criteria(ac_id TEXT NOT NULL, requirement_id TEXT NOT NULL, spec_id TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(ac_id,spec_id), FOREIGN KEY(requirement_id,spec_id) REFERENCES requirements(requirement_id,spec_id));
CREATE TABLE iterations(iteration_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),number INTEGER NOT NULL, UNIQUE(run_id,number));
CREATE TABLE tasks(task_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), iteration_id TEXT REFERENCES iterations(iteration_id), spec_id TEXT NOT NULL REFERENCES specs(spec_id), state TEXT NOT NULL CHECK(state IN ('PENDING','READY','LEASED','RUNNING','IMPLEMENTED','VERIFYING','ACCEPTED','BLOCKED','CANCELLED')), revision INTEGER NOT NULL DEFAULT 0, role TEXT NOT NULL, created_seq INTEGER NOT NULL);
CREATE TABLE task_dependencies(task_id TEXT REFERENCES tasks(task_id),depends_on TEXT REFERENCES tasks(task_id),PRIMARY KEY(task_id,depends_on),CHECK(task_id<>depends_on));
CREATE TABLE task_requirements(task_id TEXT REFERENCES tasks(task_id), requirement_id TEXT NOT NULL,spec_id TEXT NOT NULL,PRIMARY KEY(task_id,requirement_id,spec_id),FOREIGN KEY(requirement_id,spec_id) REFERENCES requirements(requirement_id,spec_id));
CREATE TABLE sessions(session_id TEXT PRIMARY KEY,agent TEXT NOT NULL,role TEXT NOT NULL,native_id TEXT,native_path TEXT,agent_version TEXT NOT NULL,capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)));
CREATE TABLE attempts(attempt_id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(task_id),session_id TEXT REFERENCES sessions(session_id),state TEXT NOT NULL CHECK(state IN ('PREPARED','STARTING','RUNNING','SETTLED','FAILED','CANCELLED','UNKNOWN_EFFECT')), role_epoch INTEGER NOT NULL,host_epoch INTEGER NOT NULL,started_at TEXT,ended_at TEXT,raw_log_path TEXT,UNIQUE(task_id,attempt_id));
CREATE TABLE leases(project_id TEXT REFERENCES projects(project_id),kind TEXT NOT NULL,attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),epoch INTEGER NOT NULL,expires_at TEXT NOT NULL,PRIMARY KEY(project_id,kind));
CREATE TABLE candidates(candidate_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),git_commit TEXT NOT NULL,git_tree TEXT NOT NULL,spec_sha256 TEXT NOT NULL CHECK(length(spec_sha256)=64),environment_sha256 TEXT NOT NULL CHECK(length(environment_sha256)=64),test_plan_sha256 TEXT NOT NULL CHECK(length(test_plan_sha256)=64),source_path TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY,sha256 TEXT NOT NULL CHECK(length(sha256)=64),path TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>=0),mime TEXT NOT NULL,UNIQUE(sha256,path));
CREATE TABLE evidence(evidence_id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id),kind TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('PASS','FAIL','INVALID','UNKNOWN','FLAKY','NOT_RUN')),mode TEXT NOT NULL CHECK(mode IN ('mock','live','product')),created_at TEXT NOT NULL);
CREATE TABLE acceptance_results(ac_id TEXT NOT NULL,spec_id TEXT NOT NULL,candidate_id TEXT NOT NULL REFERENCES candidates(candidate_id),evidence_id TEXT NOT NULL REFERENCES evidence(evidence_id),status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','INVALID','UNKNOWN')),PRIMARY KEY(ac_id,spec_id,candidate_id,evidence_id),FOREIGN KEY(ac_id,spec_id) REFERENCES acceptance_criteria(ac_id,spec_id));
CREATE TABLE issues(issue_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),candidate_id TEXT REFERENCES candidates(candidate_id),fingerprint TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('critical','high','medium','low')),state TEXT NOT NULL CHECK(state IN ('OPEN','RESOLVED','REOPENED')),description TEXT NOT NULL);
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(project_id),event_id TEXT NOT NULL UNIQUE,run_id TEXT REFERENCES runs(run_id),kind TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at TEXT NOT NULL);
CREATE INDEX events_project_seq ON events(project_id,seq);
CREATE INDEX events_run_kind ON events(run_id,kind,seq);
CREATE TABLE commands(command_id TEXT PRIMARY KEY,run_id TEXT REFERENCES runs(run_id),idempotency_key TEXT NOT NULL UNIQUE,payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64),expected_revision INTEGER NOT NULL,result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)));
CREATE TABLE outbox(message_id TEXT PRIMARY KEY,event_seq INTEGER NOT NULL REFERENCES events(seq),recipient_role TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),state TEXT NOT NULL CHECK(state IN ('PENDING','DELIVERING','ACKED','DEAD_LETTER')),attempt_count INTEGER NOT NULL DEFAULT 0,next_retry_at TEXT);
CREATE TABLE receipts(consumer TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES outbox(message_id),applied_at TEXT NOT NULL,result_json TEXT NOT NULL CHECK(json_valid(result_json)),PRIMARY KEY(consumer,message_id));
CREATE TABLE effects(effect_key TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),state TEXT NOT NULL CHECK(state IN ('PREPARED','STARTED','OBSERVED','COMMITTED','UNKNOWN')),external_ref TEXT,artifact_sha256 TEXT);
CREATE TABLE decisions(decision_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),role_epoch INTEGER NOT NULL,expected_revision INTEGER NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),state TEXT NOT NULL CHECK(state IN ('PROPOSED','APPLIED','REJECTED')));
CREATE TABLE input_queue(input_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(run_id),kind TEXT NOT NULL CHECK(kind IN ('ASK','STEER','CHANGE','CONTROL')),target_role TEXT,state TEXT NOT NULL CHECK(state IN ('QUEUED','DELIVERED','APPLIED','REJECTED')),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
INSERT OR IGNORE INTO schema_migrations VALUES(1,'2026-10-13T00:00:00Z');
